from collections import deque
def f(inp):
    H,W=len(inp),len(inp[0])
    seeds=[(y,x,inp[y][x]) for y in range(H) for x in range(W) if inp[y][x] not in (0,1)]
    dist=[[None]*W for _ in range(H)]; colof=[[None]*W for _ in range(H)]
    q=deque()
    for sy,sx,c in seeds: dist[sy][sx]=c; q.append((sy,sx))
    while q:
        y,x=q.popleft()
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<H and 0<=xx<W and dist[yy][xx] is None and inp[yy][xx]==1:
                dist[yy][xx]=dist[y][x]; colof[yy][xx]=colof[y][x]; q.append((yy,xx))
    res=[row[:] for row in inp]
    for y in range(H):
        for x in range(W):
            if inp[y][x]==1 and dist[y][x] is not None: res[y][x]=dist[y][x]
    return res
